// RawClass returns the Line_Break class of cp before LB1. A code
// point no range covers is LbXX, the default LineBreak.txt's own
// @missing: 0000..10FFFF; XX header declares.
//
// The ranges partition the code space and are sorted by lower bound,
// so the covering range is unique and a binary search finds it.
func RawClass(cp uint32) Lb {
	lo, hi := 0, len(lbRanges)
	for lo < hi {
		mid := lo + (hi-lo)/2
		entry := lbRanges[mid]
		switch {
		case cp < entry.lo:
			hi = mid
		case cp > entry.hi:
			lo = mid + 1
		default:
			return entry.class
		}
	}
	return LbXX
}

// CategoryOf returns the General_Category of cp, GcCn when no range
// covers it — the default UnicodeData.txt declares for unassigned
// code points.
//
// The ranges partition the code space and are sorted by lower bound,
// so the covering range is unique and a binary search finds it.
func CategoryOf(cp uint32) GeneralCategory {
	lo, hi := 0, len(gcRanges)
	for lo < hi {
		mid := lo + (hi-lo)/2
		entry := gcRanges[mid]
		switch {
		case cp < entry.lo:
			hi = mid
		case cp > entry.hi:
			lo = mid + 1
		default:
			return entry.class
		}
	}
	return GcCn
}

// WidthOf returns the East_Asian_Width of cp, EawN when the file
// omits it.
//
// The ranges partition the code space and are sorted by lower bound,
// so the covering range is unique and a binary search finds it.
func WidthOf(cp uint32) EastAsianWidth {
	lo, hi := 0, len(eawRanges)
	for lo < hi {
		mid := lo + (hi-lo)/2
		entry := eawRanges[mid]
		switch {
		case cp < entry.lo:
			hi = mid
		case cp > entry.hi:
			lo = mid + 1
		default:
			return entry.class
		}
	}
	return EawN
}

// IsExtendedPictographic reports whether cp has the
// Extended_Pictographic property, which LB30b and GB11 read.
//
// The ranges are sorted by lower bound and disjoint, so a binary
// search decides membership.
func IsExtendedPictographic(cp uint32) bool {
	lo, hi := 0, len(extPictRanges)
	for lo < hi {
		mid := lo + (hi-lo)/2
		entry := extPictRanges[mid]
		switch {
		case cp < entry.lo:
			hi = mid
		case cp > entry.hi:
			lo = mid + 1
		default:
			return true
		}
	}
	return false
}

// PublishedRowCount is how many data rows the pinned corpus carries,
// counted from the canonical LineBreakTest.txt at generation. The corpus
// gate asserts the rows it reads from the vendored copy against this, so
// a row lost between the two fails rather than quietly shrinking the
// denominator.
const PublishedRowCount = 19338
